    public void setClock(Clock clock) {
        this.clock = clock;
    }

    /**
     * 当前 UTC 时刻（无时区偏移量的 LocalDateTime，按 UTC 解释）。
     */
    public LocalDateTime nowUtc() {
        return LocalDateTime.now(clock);
    }
}

