22	import static org.assertj.core.api.Assertions.assertThat;
23	
24	/**
25	 * 并发与幂等边界测试：交接接受/取消/失败核验并发时按事务提交顺序生效，
26	 * 不允许出现已取消交接仍改变保管人、或封条已异常仍完成交接的结果。
27	 */
28	@SpringBootTest
29	class EvidenceConcurrencyTest {
30	
31	    @Autowired
32	    private EvidenceController controller;
33	
34	    @Autowired
35	    private EvidenceService evidenceService;
36	
37	    private String uniqueKey(String prefix) {
38	        return prefix + "-" + UUID.randomUUID().toString().substring(0, 12);
39	    }
40	
41	    private void intake(String actor, String evidenceKey) {
42	        ResponseEntity<String> response = controller.intake(actor,
43	                new IntakeRequest(uniqueKey("CMD"), evidenceKey, "CASE-1", "DOCUMENT", "SEAL-1"));
44	        assertThat(response.getStatusCode().value()).isEqualTo(201);
45	    }
46	
47	    private void initiate(String actor, String evidenceKey, String toCustodian) {
48	        ResponseEntity<String> response = controller.initiateTransfer(actor, evidenceKey,
49	                new TransferInitiateRequest(uniqueKey("CMD"), toCustodian));
50	        assertThat(response.getStatusCode().value()).isEqualTo(200);
51	    }
52	
53	    /**
54	     * 记录一次并发调用的 HTTP 状态码（业务异常取其携带状态码）。
55	     */
56	    private static final class StatusCall implements Callable<Integer> {
57	        private final CountDownLatch ready;
58	        private final CountDownLatch start;
59	        private final Callable<ResponseEntity<String>> call;
60	
61	        StatusCall(CountDownLatch ready, CountDownLatch start, Callable<ResponseEntity<String>> call) {
62	            this.ready = ready;
63	            this.start = start;
64	            this.call = call;
65	        }
66	
67	        @Override
68	        public Integer call() throws Exception {
69	            ready.countDown();
70	            start.await(5, TimeUnit.SECONDS);
71	            try {
72	                return call.call().getStatusCode().value();
73	            } catch (ApiException e) {
74	                return e.status().value();
75	            }
76	        }
77	    }
78	
79	    private List<Integer> runConcurrently(Callable<ResponseEntity<String>> first,
80	                                          Callable<ResponseEntity<String>> second) throws Exception {
81	        ExecutorService executor = Executors.newFixedThreadPool(2);
82	        try {
83	            CountDownLatch ready = new CountDownLatch(2);
84	            CountDownLatch start = new CountDownLatch(1);
85	            Future<Integer> f1 = executor.submit(new StatusCall(ready, start, first));
86	            Future<Integer> f2 = executor.submit(new StatusCall(ready, start, second));
87	            assertThat(ready.await(5, TimeUnit.SECONDS)).isTrue();
88	            start.countDown();
89	            return List.of(f1.get(15, TimeUnit.SECONDS), f2.get(15, TimeUnit.SECONDS));
90	        } finally {
91	            executor.shutdownNow();
92	        }
93	    }
94	
95	    @Test
96	    void concurrentAcceptAndCancelExactlyOneWins() throws Exception {
97	        String evidenceKey = uniqueKey("EV");
98	        intake("alice", evidenceKey);
99	        initiate("alice", evidenceKey, "bob");
100	
101	        List<Integer> statuses = runConcurrently(
102	                () -> controller.acceptTransfer("bob", evidenceKey,
103	                        new CommandRequest(uniqueKey("CMD"))),
104	                () -> controller.cancelTransfer("alice", evidenceKey,
105	                        new CommandRequest(uniqueKey("CMD"))));
106	
107	        assertThat(statuses).containsExactlyInAnyOrder(200, 409);
108	        var chain = evidenceService.custodyChain(evidenceKey);
109	        assertThat(chain.transfers()).hasSize(1);
110	        var transfer = chain.transfers().get(0);
111	        if (transfer.status() == TransferStatus.ACCEPTED) {
112	            // 接受先提交：保管人必须已切换
113	            assertThat(chain.evidence().custodianId()).isEqualTo("bob");
114	            assertThat(chain.evidence().status()).isEqualTo(EvidenceStatus.SEALED);
115	        } else {
116	            // 取消先提交：保管人不得被已取消的交接改变
117	            assertThat(transfer.status()).isEqualTo(TransferStatus.CANCELLED);
118	            assertThat(chain.evidence().custodianId()).isEqualTo("alice");
119	            assertThat(chain.evidence().status()).isEqualTo(EvidenceStatus.SEALED);
120	        }
121	    }
122	
123	    @Test
124	    void concurrentFailedInspectionAndAcceptNeverCompleteTransferOnBrokenSeal() throws Exception {
125	        String evidenceKey = uniqueKey("EV");
126	        intake("alice", evidenceKey);
127	        initiate("alice", evidenceKey, "bob");
128	
129	        List<Integer> statuses = runConcurrently(
130	                () -> controller.acceptTransfer("bob", evidenceKey,
131	                        new CommandRequest(uniqueKey("CMD"))),
132	                () -> controller.inspectSeal("alice", evidenceKey,
133	                        new SealInspectionRequest(uniqueKey("CMD"), false, "cracked")));
134	
135	        // 核验先提交则接受得到 422；接受先提交则旧保管人核验得到 409
136	        assertThat(statuses.stream().filter(s -> s == 200).count()).isEqualTo(1);
137	        assertThat(statuses).allMatch(s -> s == 200 || s == 409 || s == 422);
138	
139	        var chain = evidenceService.custodyChain(evidenceKey);
140	        var transfer = chain.transfers().get(0);
141	        if (transfer.status() == TransferStatus.ACCEPTED) {
142	            // 接受先提交：交接完成时封条尚未异常，保管人已切换
143	            assertThat(chain.evidence().custodianId()).isEqualTo("bob");
144	        } else {
145	            // 失败核验先提交：封条异常，交接不得完成，保管人不变
146	            assertThat(chain.evidence().status()).isEqualTo(EvidenceStatus.SEAL_BROKEN);
147	            assertThat(chain.evidence().custodianId()).isEqualTo("alice");
148	            assertThat(transfer.status()).isEqualTo(TransferStatus.PENDING);
149	        }
150	    }
151	
152	    @Test
153	    void concurrentDuplicateIntakeWithSameCommandKeyReplaysSingleResult() throws Exception {
154	        String evidenceKey = uniqueKey("EV");
155	        String commandKey = uniqueKey("CMD");
156	        IntakeRequest request = new IntakeRequest(commandKey, evidenceKey, "CASE-1", "DOCUMENT", "SEAL-1");
157	
158	        List<Integer> statuses = runConcurrently(
159	                () -> controller.intake("alice", request),
160	                () -> controller.intake("alice", request));
161	
162	        assertThat(statuses).containsOnly(201);
163	        var chain = evidenceService.custodyChain(evidenceKey);
164	        assertThat(chain.evidence().custodianId()).isEqualTo("alice");
165	        assertThat(chain.transfers()).isEmpty();
166	    }
167	}
