package com.example.starter.evidence;

/**
 * 保留冻结级别。
 * CASE 案件级冻结（作用于案件下全部证物）；EVIDENCE 单件证物级冻结（仅作用于该证物）。
 */
public enum HoldScope {
    CASE,
    EVIDENCE
}

package com.example.starter.evidence;

/**
 * 冻结在查询时刻的有效状态（查询时按 UTC 时钟即时计算，不写库）。
 * ACTIVE 生效中（未解除且未到期）；RELEASED 已由保管人解除；EXPIRED 已自然到期。
 */
public enum HoldState {
    ACTIVE,
    RELEASED,
    EXPIRED
}

package com.example.starter.evidence;

/**
 * 销毁申请审批结果。
 * APPROVED 满足业务条件且无有效冻结，证物进入 DESTROYED；
 * REJECTED 被证物自身或所属案件的有效冻结阻断（HTTP 409，证物状态不变，记录只追加保留）。
 */
public enum DestructionStatus {
    APPROVED,
    REJECTED
}

