/**
 * 按业务键查询并锁定证物行（SELECT ... FOR UPDATE），用于一切状态/保管人变更。
 */
public Optional<Evidence> findByKeyForUpdate(String evidenceKey) {
    List<Evidence> rows = jdbc.query(
            "SELECT * FROM evidence WHERE evidence_key = ? FOR UPDATE", ROW_MAPPER, evidenceKey);
    return rows.stream().findFirst();
}

/**
 * 锁定指定案件下的全部证物行（按 id 稳定顺序加锁，避免案件级冻结与销毁并发时跨事务死锁）。
 * 案件级冻结创建、销毁申请的案件冻结检查均通过该方法串行化。
 */
public List<Evidence> findByCaseKeyForUpdate(String caseKey) {
    return jdbc.query(
            "SELECT * FROM evidence WHERE case_key = ? ORDER BY id FOR UPDATE",
            ROW_MAPPER, caseKey);
}

/**
 * 按案件键查询全部证物（不加锁），用于只读展示。
 */
