                .isEqualTo(409);

        // 交接给 bob 后，由不同于创建人的现任保管人 bob 解除
        assertThat(initiate("alice", evidenceKey, "bob").getStatus()).isEqualTo(200);
        assertThat(accept("bob", evidenceKey).getStatus()).isEqualTo(200);
        MvcResult released = release("bob", holdKey, uniqueKey("CMD"), "鉴定完毕解除保留");
        assertThat(released.getStatus()).isEqualTo(200);
