        String caseHold = uniqueKey("HOLD-CASE");
        assertThat(holdEvidence("alice", evidenceKey, uniqueKey("CMD"), evHold,
                LocalDateTime.parse("2026-09-30T11:30:00"), "证物短期冻结").getStatus())
